#!/usr/bin/env python3
from __future__ import annotations
import argparse, re
from pathlib import Path

SOLUTIONS = {31: ['Since \\(D^r/S^{r-1}\\cong S^r\\), relative cohomology is reduced cohomology of \\(S^r\\):\n\\[\nH^q(D^r,S^{r-1};\\mathbb Z)\\cong\n\\begin{cases}\\mathbb Z,&q=r,\\\\0,&q\\ne r.\\end{cases}\n\\]\nThe generator is the orientation class of the disk fiber.', 'For a rank-three oriented bundle \\(E\\to S^2\\),\n\\[\n\\Phi_E:H^k(S^2)\\xrightarrow{\\cong}H^{k+3}(D(E),S(E)),\n\\qquad \\alpha\\mapsto\\pi^*\\alpha\\smile u_E.\n\\]\nThus \\(1\\in H^0(S^2)\\) maps to \\(u_E\\in H^3\\), while the degree-two generator maps to a degree-five relative class.', 'For \\(E=B\\times\\mathbb R\\), the fiber pair over \\(b\\) is \\((D^1,S^0)\\). Choose \\(u_E\\) so that\n\\[\nu_E|_{(D^1,S^0)}=1\\in H^1(D^1,S^0;\\mathbb Z).\n\\]\nThis fiberwise generator condition is exactly the Thom normalization.', 'Reversing the orientation reverses the chosen generator of every fiber group \\(H^r(D^r,S^{r-1};\\mathbb Z)\\). By uniqueness of the normalized class, the new Thom class is \\(-u_E\\).', 'The only ambiguity in an integral fiber generator is its sign. In \\(\\mathbb Z/2\\), \\(1=-1\\), so local generators glue without an orientation choice. Hence every real vector bundle has a mod-two Thom class.', 'For \\(E=B\\times\\mathbb R^r\\),\n\\[\n\\operatorname{Th}(E)=D(E)/S(E)\\cong B_+\\wedge(D^r/S^{r-1})\n\\cong B_+\\wedge S^r.\n\\]', 'With \\(B=S^1\\),\n\\[\n\\operatorname{Th}(E)\\simeq S^1_+\\wedge S^r\\simeq S^r\\vee S^{r+1}.\n\\]\nTherefore its reduced integral cohomology is \\(\\mathbb Z\\) in degrees \\(r\\) and \\(r+1\\), and zero otherwise.', 'If \\(f:Y\\to B\\), the bundle map \\(\\widetilde f:D(f^*E)\\to D(E)\\) covering \\(f\\) pulls the Thom class back:\n\\[\nu_{f^*E}=\\widetilde f^{\\,*}u_E.\n\\]\nIts restriction to every pulled-back fiber is the same oriented generator.', "For \\(\\alpha\\in H^k(B)\\),\n\\[\n\\widetilde f^{\\,*}(\\pi^*\\alpha\\smile u_E)\n=(\\pi')^*(f^*\\alpha)\\smile u_{f^*E}.\n\\]\nThus pullback commutes with the two Thom isomorphisms.", 'The equator \\(S^{n-1}\\subset S^n\\) has a one-dimensional normal bundle. A continuous unit normal can be chosen pointing toward one hemisphere, so this normal line bundle is trivial:\n\\[\n\\nu\\cong S^{n-1}\\times\\mathbb R.\n\\]', 'Using the normal coordinate, a tubular neighborhood is\n\\[\nS^{n-1}\\times(-\\varepsilon,\\varepsilon)\\longrightarrow S^n,\n\\]\nwith \\(S^{n-1}\\times\\{0\\}\\) identified with the equator. Radial/geodesic normal displacement gives the embedding.', 'Collapse the complement of the chosen tubular neighborhood to one point, and identify the neighborhood with \\(D(\\nu)\\). This gives\n\\[\nS^n\\longrightarrow D(\\nu)/S(\\nu)=\\operatorname{Th}(\\nu).\n\\]', 'For any good pair,\n\\[\nH^q(D(E),S(E))\\cong \\widetilde H^q(D(E)/S(E)).\n\\]\nSince \\(D(E)/S(E)=\\operatorname{Th}(E)\\), relative Thom cohomology is exactly reduced cohomology of the Thom quotient.', 'For the bundle \\(\\mathbb R^r\\to\\{\\ast\\}\\), one-point compactification gives \\(S^r\\). Hence\n\\[\nH_c^q(\\mathbb R^r;\\mathbb Z)\\cong\\widetilde H^q(S^r;\\mathbb Z),\n\\]\nwhich is \\(\\mathbb Z\\) in degree \\(r\\) and zero otherwise.', 'For a rank-five oriented bundle,\n\\[\nH^k(B)\\xrightarrow{\\cong}H^{k+5}(D(E),S(E)).\n\\]\nFor example a class in \\(H^2(B)\\) corresponds to a relative class in degree \\(7\\).', 'Two bundle metrics are joined by a continuous path of positive-definite metrics. Fiberwise radial rescaling identifies their disk/sphere pairs through an isotopy, and the normalized fiber generator is preserved. Thus the induced Thom classes correspond.', 'An orientation-preserving bundle isomorphism sends each oriented fiber generator to the oriented fiber generator. Pullback of the target Thom class therefore satisfies the defining normalization, so by uniqueness it equals the source Thom class.', 'An orientation-reversing bundle isomorphism sends the fiber orientation generator to its negative. Consequently the pulled-back integral Thom class is \\(-u_E\\); modulo two there is no sign change.', 'For an oriented embedding \\(i:N\\hookrightarrow M\\), first choose a tubular neighborhood \\(D(\\nu)\\subset M\\) of the normal bundle. Cup with \\(u_\\nu\\) on that neighborhood, then use excision and extension to ambient cohomology. This is the geometric core of the Gysin map.', 'The zero section is \\(s(b)=0_b\\). Since \\(0_b\\) lies in the interior of every fiber disk \\(D(E_b)\\), the image \\(s(B)\\) meets every disk fiber at its center and never lies in the sphere boundary.', 'A trivial positive-rank bundle has a nowhere-zero constant section, so its Euler class vanishes. Since \\(e(E)=s^*u_E\\),\n\\[\ns^*u_E=0.\n\\]', "A nowhere-zero section can be normalized to a section of \\(S(E)\\). The Euler class is the obstruction represented by the zero section's pullback of the Thom class; a section avoiding zero makes that obstruction vanish. Hence a nowhere-zero section forces \\(s^*u_E=e(E)=0\\).", 'For an oriented embedded submanifold \\(N\\subset M\\), take the Thom class of its oriented normal bundle, identify the disk bundle with a tubular neighborhood, and extend by excision into \\(M\\). The resulting ambient cohomology class is \\(\\operatorname{PD}[N]\\).', 'The chain is\n\\[\nu_E\\in H^r(D(E),S(E))\n\\;\\xrightarrow{s^*}\\;\ne(E)\\in H^r(B)\n\\;\\xrightarrow{\\frown[B]}\\;\nH_{\\dim B-r}(B).\n\\]\nThus the Thom class produces the Euler class, and cap product with the fundamental class converts it into its geometric dual cycle.'], 32: ['For \\(E=S^1\\times\\mathbb R^2\\), the unit vectors in each fiber form \\(S^1\\), so\n\\[\nS(E)\\cong S^1\\times S^1\\to S^1.\n\\]\nIt is the trivial circle bundle.', 'If \\(s(b)\\ne0\\) for all \\(b\\), define \\(\\widehat s(b)=s(b)/\\|s(b)\\|\\). Continuity of the norm gives a continuous section \\(\\widehat s:B\\to S(E)\\). Conversely, including \\(S(E)\\subset E\\) turns every sphere-bundle section into a nowhere-zero section.', 'Thom naturality gives \\(u_{f^*E}=\\widetilde f^{\\,*}u_E\\). Pulling back along the zero sections yields\n\\[\ne(f^*E)=s_Y^*u_{f^*E}=s_Y^*\\widetilde f^{\\,*}u_E=f^*s_B^*u_E=f^*e(E).\n\\]', 'A trivial rank-three bundle admits a constant nowhere-zero section. Therefore its Euler class is zero:\n\\[\ne(B\\times\\mathbb R^3)=0\\in H^3(B).\n\\]', 'By multiplicativity,\n\\[\ne(E\\oplus\\varepsilon^1)=e(E)\\smile e(\\varepsilon^1).\n\\]\nThe trivial line has a nowhere-zero section, so \\(e(\\varepsilon^1)=0\\), and the product vanishes.', 'For the oriented two-sphere,\n\\[\n\\langle e(TS^2),[S^2]\\rangle=\\chi(S^2)=2.\n\\]\nThus the Euler class is twice the preferred generator of \\(H^2(S^2;\\mathbb Z)\\).', 'If \\(TS^2\\) had a nowhere-zero section, the Euler class would vanish. But its evaluation on \\([S^2]\\) is \\(2\\), so \\(e(TS^2)\\ne0\\). Hence no nowhere-zero tangent vector field exists.', 'For every \\(m\\ge1\\),\n\\[\n\\langle e(TS^{2m}),[S^{2m}]\\rangle=\\chi(S^{2m})=2.\n\\]\nSo the tangent Euler number of every even-dimensional sphere is \\(2\\).', 'For \\(S^{2m+1}\\),\n\\[\n\\langle e(TS^{2m+1}),[S^{2m+1}]\\rangle=\\chi(S^{2m+1})=0.\n\\]\nIndeed odd spheres admit explicit nowhere-zero tangent vector fields.', 'A tangent vector field is a section of \\(TM\\), and after normalization a nowhere-zero vector field is a section of \\(S(TM)\\). Since \\(e(TS^{2m})\\ne0\\), the Euler obstruction rules out such a section. This is the hairy-ball theorem.', 'For an oriented rank-two bundle \\(E\\to B\\), the sphere fiber is \\(S^1\\), and the Gysin sequence contains\n\\[\n\\cdots\\to H^{k-2}(B)\\xrightarrow{\\smile e(E)}H^k(B)\n\\to H^k(S(E))\\to H^{k-1}(B)\\xrightarrow{\\smile e(E)}H^{k+1}(B)\\to\\cdots.\n\\]', 'In the Gysin sequence the characteristic map from base cohomology to base cohomology is precisely\n\\[\n\\alpha\\longmapsto \\alpha\\smile e(E).\n\\]\nIts degree shift equals the rank of the oriented vector bundle.', 'If \\(\\operatorname{rank}E=r=\\dim B\\), transversality to the zero section makes the zero set of a generic section a submanifold of dimension \\(r-r=0\\). On a compact base it is therefore a finite set of isolated zeros.', 'At an isolated transverse zero \\(x\\), trivialize \\(E\\) and orient both base and fiber. The derivative of the local section is an isomorphism \\(T_xB\\to E_x\\). Assign sign \\(+1\\) if it preserves orientation and \\(-1\\) if it reverses orientation.', 'The local signs are local degrees. Their sum equals the Euler number:\n\\[\n\\sum_{x:s(x)=0}\\operatorname{ind}_x(s)\n=\\langle e(E),[B]\\rangle.\n\\]\nFor \\(E=TB\\) this is Poincaré--Hopf.', 'With \\(\\mathbb Z/2\\) coefficients, the signs \\(+1\\) and \\(-1\\) coincide. Thus the zero locus is counted modulo two, and the mod-two Thom/Euler obstruction is defined without orienting the bundle.', 'Pulling a positive-rank bundle back to a point gives a vector space over a point. Since \\(H^r(\\{\\ast\\})=0\\) for \\(r>0\\),\n\\[\ne(i^*E)=i^*e(E)=0.\n\\]\nThis is consistent with every vector space admitting nonzero vectors.', 'For example, on \\(S^2\\times S^2\\) let\n\\[\nE=p_1^*TS^2\\oplus p_2^*TS^2.\n\\]\nThen\n\\[\ne(E)=p_1^*e(TS^2)\\smile p_2^*e(TS^2),\n\\]\nand its evaluation on \\([S^2\\times S^2]\\) is \\(2\\cdot2=4\\).', 'Since \\(T(M\\times N)\\cong p_M^*TM\\oplus p_N^*TN\\),\n\\[\ne(T(M\\times N))=p_M^*e(TM)\\smile p_N^*e(TN).\n\\]\nEvaluating gives \\(\\chi(M\\times N)=\\chi(M)\\chi(N)\\), illustrating Whitney-sum multiplicativity.', 'The Euler class is only one characteristic class. In higher rank or on complicated bases, two nonisomorphic bundles can share the same Euler class but differ in other characteristic data such as Stiefel--Whitney or Pontryagin classes. Therefore \\(e(E)=0\\) alone is not a complete classification.', 'For an oriented rank-\\(r\\) bundle, the fiber of \\(S(E)\\) is \\(S^{r-1}\\). The primary obstruction to extending a section lies in\n\\[\nH^r(B;\\pi_{r-1}(S^{r-1}))\\cong H^r(B;\\mathbb Z)\n\\]\n(with the appropriate orientation local system), and this obstruction is the Euler class.', 'A transverse section \\(s\\) meets the zero section cleanly. Pulling the normal Thom class through this intersection identifies the cohomology class detecting the zero set with \\(s^*u_E=e(E)\\). Thus the Thom class localizes the zero locus.', 'If \\(Z=s^{-1}(0)\\) is transverse, then \\(Z\\) has codimension \\(r\\) and its normal bundle is naturally \\(E|_Z\\). The Thom construction therefore yields\n\\[\n\\operatorname{PD}[Z]=e(E).\n\\]', 'The geometry and algebra line up as\n\\[\n\\text{section of }S(E)\n\\Longleftrightarrow\n\\text{nowhere-zero section of }E,\n\\]\nwhile failure of such a section is detected first by \\(e(E)\\). For a transverse section, its zero set represents \\(\\operatorname{PD}(e(E))\\), leading directly to Poincaré duality.'], 33: ['For a closed oriented \\(n\\)-sphere,\n\\[\nH^0(S^n)\\cong H_n(S^n)\\cong\\mathbb Z,\\qquad\nH^n(S^n)\\cong H_0(S^n)\\cong\\mathbb Z,\n\\]\nand all other groups vanish. Cap product with \\([S^n]\\) gives these two isomorphisms.', 'For a genus-\\(g\\) closed oriented surface,\n\\[\n(b_0,b_1,b_2)=(1,2g,1).\n\\]\nPoincaré duality gives the symmetry \\(b_0=b_2\\), while the middle group is self-dual.', 'Choose \\(a,b\\in H^1(T^2;\\mathbb Z)\\) with \\(\\langle a\\smile b,[T^2]\\rangle=1\\). Since degree-one cup product is skew-commutative,\n\\[\n\\bigl(\\langle x_i\\smile x_j,[T^2]\\rangle\\bigr)\n=\n\\begin{pmatrix}0&1\\\\-1&0\\end{pmatrix}.\n\\]', 'Let \\(A=S^1\\times\\{\\ast\\}\\subset T^2\\). Its Poincaré dual is the degree-one class that evaluates by intersection with \\(A\\); in the standard basis it is the cohomology class dual to the transverse factor circle.', 'The two standard circles \\(S^1\\times\\{\\ast\\}\\) and \\(\\{\\ast\\}\\times S^1\\) meet in exactly one point. With the product orientation and compatible orientations of the circles, the local intersection sign is \\(+1\\).', 'If \\(\\alpha,\\beta\\) are the dual cohomology classes of the two standard circles, then\n\\[\nA\\cdot B=\\langle\\alpha\\smile\\beta,[T^2]\\rangle=1.\n\\]\nThus the signed geometric intersection is exactly the cup-product pairing.', 'For \\(\\mathbb{CP}^2\\),\n\\[\nH_k(\\mathbb{CP}^2;\\mathbb Z)\\cong\n\\begin{cases}\\mathbb Z,&k=0,2,4,\\\\0,&\\text{otherwise},\\end{cases}\n\\]\nand Poincaré duality pairs degrees \\(0\\leftrightarrow4\\) and \\(2\\leftrightarrow2\\).', 'If \\(h\\in H^2(\\mathbb{CP}^2;\\mathbb Z)\\) is the positive generator, then \\(h^2\\) is the orientation class and\n\\[\n\\langle h^2,[\\mathbb{CP}^2]\\rangle=1.\n\\]', 'For a closed oriented \\(n=2m+1\\) manifold, \\(b_k=b_{n-k}\\). The paired terms in\n\\[\n\\chi(M)=\\sum_k(-1)^k b_k\n\\]\nhave opposite signs because \\(n\\) is odd, so they cancel and \\(\\chi(M)=0\\).', 'An orientation is a compatible family of generators of\n\\[\nH_n(M,M\\setminus\\{x\\};\\mathbb Z)\\cong\\mathbb Z.\n\\]\nCompactness permits these compatible local generators to assemble into the unique global class \\([M]\\in H_n(M;\\mathbb Z)\\) restricting to each chosen generator.', 'If \\(\\alpha\\in H^k(M)\\) and \\(c\\in H_n(M)\\), then\n\\[\n\\alpha\\frown c\\in H_{n-k}(M).\n\\]\nThus cap product lowers homological degree by exactly the cohomological degree.', 'If \\(f:M\\to N\\) is orientation preserving, then \\(f_*[M]=[N]\\). Naturality of cup/cap evaluation gives\n\\[\n\\langle f^*\\alpha,[M]\\rangle=\\langle\\alpha,f_*[M]\\rangle=\\langle\\alpha,[N]\\rangle.\n\\]', 'For \\(i:N^{n-r}\\hookrightarrow M^n\\), choose an oriented tubular neighborhood \\(D(\\nu)\\). The Thom class \\(u_\\nu\\in H^r(D(\\nu),S(\\nu))\\) extends by excision to a class in \\(H^r(M,M\\setminus N)\\) and then to \\(H^r(M)\\). This is \\(\\operatorname{PD}[N]\\).', 'The Thom collapse\n\\[\nM\\to\\operatorname{Th}(\\nu)\n\\]\npulls the Thom class back to the ambient dual class of \\(N\\). Thus the collapse-map construction and the tubular-neighborhood construction give the same Poincaré dual.', 'For a transverse section of an oriented rank-\\(r\\) bundle, the zero set \\(Z\\) has normal bundle \\(E|_Z\\). Its normal Thom class is the restriction of the bundle Thom class, so\n\\[\n\\operatorname{PD}[Z]=e(E).\n\\]', 'For a compact oriented \\(n\\)-manifold with boundary,\n\\[\nH^k(M;R)\\cong H_{n-k}(M,\\partial M;R),\n\\qquad\nH^k(M,\\partial M;R)\\cong H_{n-k}(M;R).\n\\]\nThe fundamental class is relative: \\([M,\\partial M]\\in H_n(M,\\partial M)\\).', 'For \\(I=[0,1]\\),\n\\[\nH^0(I)\\cong\\mathbb Z\\cong H_1(I,\\partial I),\n\\]\nwhile \\(H^1(I)=0\\cong H_0(I,\\partial I)\\). The relative fundamental class is the oriented interval.', 'For \\(D^n\\),\n\\[\nH^0(D^n)\\cong\\mathbb Z\\cong H_n(D^n,S^{n-1}),\n\\]\nand all other corresponding groups vanish. This is the basic local model for Poincaré--Lefschetz duality.', 'On a nonorientable manifold the local orientation generators cannot be chosen coherently, so there is no global integral fundamental class in ordinary coefficients. Consequently the ordinary integral cap-product isomorphism fails.', 'With \\(\\mathbb Z/2\\) coefficients, the sign ambiguity disappears. Every manifold has a mod-two fundamental class, and\n\\[\nH^k(M;\\mathbb Z/2)\\cong H_{n-k}(M;\\mathbb Z/2)\n\\]\nfor closed manifolds.', 'For a closed oriented four-manifold, middle-degree duality is\n\\[\nH^2(M;R)\\times H^2(M;R)\\to R,\\qquad\n(\\alpha,\\beta)\\mapsto\\langle\\alpha\\smile\\beta,[M]\\rangle.\n\\]\nBecause degree two is even, this pairing is symmetric.', 'The bilinear form in the previous exercise is the intersection form\n\\[\nQ_M(\\alpha,\\beta)=\\langle\\alpha\\smile\\beta,[M]\\rangle\n\\]\non middle cohomology (or, integrally, on its free lattice). This is the invariant studied in VIII/34.', 'Represent \\(\\operatorname{PD}^{-1}(\\alpha)\\) and \\(\\operatorname{PD}^{-1}(\\beta)\\) by transverse oriented surfaces. Each intersection point contributes a sign, and the signed total equals\n\\[\n\\langle\\alpha\\smile\\beta,[M]\\rangle.\n\\]', 'The fundamental class turns cohomology into complementary-dimensional homology by cap product. Geometric representatives of those dual homology classes intersect according to cup product. In the middle dimension this complementary-degree pairing becomes the intersection form.'], 34: ['Since \\(H^2(S^4;\\mathbb Z)=0\\), the free middle cohomology lattice is zero. Hence \\(Q_{S^4}\\) is the unique rank-zero bilinear form.', 'With \\(h\\) the positive generator of \\(H^2(\\mathbb{CP}^2;\\mathbb Z)\\),\n\\[\n\\langle h^2,[\\mathbb{CP}^2]\\rangle=1.\n\\]\nThus the matrix is \\([1]\\).', 'Orientation reversal replaces the fundamental class by its negative. Therefore\n\\[\nQ_{-\\mathbb{CP}^2}=-Q_{\\mathbb{CP}^2}=[-1].\n\\]', 'For the factor classes \\(a,b\\),\n\\[\na^2=b^2=0,\\qquad \\langle a b,[S^2\\times S^2]\\rangle=1.\n\\]\nHence\n\\[\nQ=\\begin{pmatrix}0&1\\\\1&0\\end{pmatrix}=H.\n\\]', 'Over \\(\\mathbb R\\), the vectors \\((1,1)\\) and \\((1,-1)\\) are eigenvectors of \\(H\\) with eigenvalues \\(1\\) and \\(-1\\), respectively. So \\(H\\) is congruent over \\(\\mathbb R\\) to \\(\\operatorname{diag}(1,-1)\\).', 'The hyperbolic form has one positive and one negative eigenvalue, so\n\\[\nb_2^+=1,\\qquad b_2^-=1,\\qquad \\sigma(H)=0.\n\\]', 'For \\(v=(x,y)\\in\\mathbb Z^2\\),\n\\[\nQ(v,v)=2xy,\n\\]\nwhich is always even. Thus \\(H\\) is an even integral form.', 'For the generator \\(1\\in\\mathbb Z\\), the form \\([1]\\) has \\(Q(1,1)=1\\), which is odd. Hence it is an odd form.', 'Connected sum gives orthogonal direct sum:\n\\[\nQ_{\\mathbb{CP}^2\\#\\mathbb{CP}^2}\\cong[1]\\oplus[1]\n=\\begin{pmatrix}1&0\\\\0&1\\end{pmatrix}.\n\\]\nIt is positive definite with signature \\(2\\).', 'Similarly,\n\\[\nQ_{\\mathbb{CP}^2\\#(-\\mathbb{CP}^2)}\n\\cong[1]\\oplus[-1]\n=\\begin{pmatrix}1&0\\\\0&-1\\end{pmatrix}.\n\\]\nIt is indefinite and has signature \\(0\\).', 'For \\(\\mathbb{CP}^2\\#\\mathbb{CP}^2\\), \\((b_2^+,b_2^-)=(2,0)\\). For \\(\\mathbb{CP}^2\\#(-\\mathbb{CP}^2)\\), \\((b_2^+,b_2^-)=(1,1)\\).', 'Since \\(Q_M(\\alpha,\\beta)=\\langle\\alpha\\smile\\beta,[M]\\rangle\\) and \\([-M]=-[M]\\),\n\\[\nQ_{-M}(\\alpha,\\beta)=-Q_M(\\alpha,\\beta).\n\\]\nThus every representing matrix is negated.', "If the old coordinate vector is \\(x=Py\\), then\n\\[\nQ(x,x')=y^T(P^TAP)y'.\n\\]\nHence an integral basis change \\(P\\in GL_r(\\mathbb Z)\\) sends \\(A\\) to \\(P^TAP\\).", 'If \\(A\\) is unimodular, \\(\\det A=\\pm1\\). Under \\(A\\mapsto P^TAP\\),\n\\[\n\\det(P^TAP)=\\det(P)^2\\det(A)=\\det(A)\n\\]\nbecause \\(\\det P=\\pm1\\). So unimodularity is basis independent.', 'In dimension four the middle degree is \\(2\\). Graded commutativity gives\n\\[\n\\alpha\\smile\\beta=(-1)^{2\\cdot2}\\beta\\smile\\alpha=\\beta\\smile\\alpha,\n\\]\nso \\(Q_M\\) is symmetric.', 'For a closed oriented surface the middle degree is \\(1\\), so\n\\[\n\\alpha\\smile\\beta=-\\beta\\smile\\alpha.\n\\]\nTherefore the degree-one intersection pairing is skew-symmetric.', 'Take\n\\[\nA=S^2\\times\\{q\\},\\qquad B=\\{p\\}\\times S^2.\n\\]\nTheir homology classes generate \\(H_2(S^2\\times S^2)\\cong\\mathbb Z^2\\).', 'The factor spheres \\(A\\) and \\(B\\) meet transversely at the single point \\((p,q)\\). With product orientations the sign is \\(+1\\), so \\(A\\cdot B=1\\).', "A small push-off of \\(A=S^2\\times\\{q\\}\\) is \\(S^2\\times\\{q'\\}\\), disjoint from \\(A\\); hence \\(A^2=0\\). The same argument gives \\(B^2=0\\).", 'For an oriented middle-dimensional submanifold \\(A\\), a transverse push-off is determined by a section of its normal bundle. Its zeros count the self-intersection, so\n\\[\nA\\cdot A=\\langle e(\\nu_A),[A]\\rangle.\n\\]', 'If \\(x\\) is torsion, say \\(mx=0\\), then for any \\(y\\),\n\\[\nmQ(x,y)=Q(mx,y)=0\n\\]\nin \\(\\mathbb Z\\), hence \\(Q(x,y)=0\\). Therefore the integer-valued lattice form factors through the free quotient.', 'Rank records lattice dimension; parity records whether all squares are even; definiteness records the sign pattern over \\(\\mathbb R\\); signature is \\(b^+-b^-\\). These are preserved under integral congruence but capture different information.', 'For\n\\[\nH\\oplus[1],\n\\]\na natural basis gives\n\\[\n\\begin{pmatrix}\n0&1&0\\\\\n1&0&0\\\\\n0&0&1\n\\end{pmatrix}.\n\\]\nIt is unimodular and indefinite, with signature \\(1\\).', 'For \\(f:M\\to M\\), fixed points satisfy \\((x,f(x))=(x,x)\\), so they are intersections of the graph \\(\\Gamma_f\\) with the diagonal \\(\\Delta\\) in \\(M\\times M\\). VIII/35 turns their signed intersection number into the Lefschetz trace.'], 35: ['For the identity, \\(L(\\mathrm{id}_X)=\\chi(X)\\). Hence\n\\[\nL(\\mathrm{id}_{S^n})=\\chi(S^n)=1+(-1)^n,\n\\]\nequal to \\(2\\) for even \\(n\\) and \\(0\\) for odd \\(n\\).', 'Only \\(H_0(S^n)\\) and \\(H_n(S^n)\\) are nonzero. The induced maps have traces \\(1\\) and \\(d\\), so\n\\[\nL(f)=1+(-1)^n d.\n\\]', 'For \\(S^2\\),\n\\[\nL(f)=1+d.\n\\]\nLefschetz forces a fixed point whenever \\(d\\ne-1\\). The theorem is silent when \\(d=-1\\).', 'For \\(S^1\\),\n\\[\nL(f)=1-d.\n\\]\nThus a fixed point is forced whenever \\(d\\ne1\\).', 'A constant map on a connected space induces the identity on \\(H_0\\) and zero on positive reduced homology. Therefore\n\\[\nL(f)=1.\n\\]', "Every self-map \\(f:D^n\\to D^n\\) has \\(L(f)=1\\), since the disk is contractible and connected. The Lefschetz fixed-point theorem therefore guarantees a fixed point. This is Brouwer's theorem.", 'Homotopic maps induce identical maps on every homology group. Their traces agree degree by degree, hence their alternating trace sums agree:\n\\[\nf\\simeq g\\implies L(f)=L(g).\n\\]', 'The Lefschetz theorem says \\(L(f)\\ne0\\Rightarrow\\operatorname{Fix}(f)\\ne\\varnothing\\). Taking the contrapositive gives\n\\[\n\\operatorname{Fix}(f)=\\varnothing\\Rightarrow L(f)=0.\n\\]', 'The identity on \\(S^1\\) has every point fixed but\n\\[\nL(\\mathrm{id}_{S^1})=\\chi(S^1)=0.\n\\]\nThus \\(L(f)=0\\) does not imply that the fixed-point set is empty.', 'The graph and diagonal are\n\\[\n\\Gamma_f=\\{(x,f(x)):x\\in M\\},\\qquad\n\\Delta=\\{(x,x):x\\in M\\}\\subset M\\times M.\n\\]', 'A point lies in both submanifolds exactly when\n\\[\n(x,f(x))=(x,x),\n\\]\nwhich is equivalent to \\(f(x)=x\\). Hence \\(\\Gamma_f\\cap\\Delta\\) is naturally the fixed-point set.', 'At a transverse intersection of \\(\\Gamma_f\\) and \\(\\Delta\\), the orientations of their tangent spaces determine a local intersection sign. For a nondegenerate smooth fixed point this sign is\n\\[\n\\operatorname{sign}\\det(I-Df_x),\n\\]\nthe local fixed-point index.', 'For \\(A=\\begin{pmatrix}2&0\\\\0&2\\end{pmatrix}\\),\n\\[\nL(f)=1-\\operatorname{tr}A+\\det A=1-4+4=1.\n\\]\nEquivalently \\(\\det(I-A)=\\det(-I)=1\\), so a fixed point is forced.', 'For \\(A=\\begin{pmatrix}1&1\\\\0&1\\end{pmatrix}\\),\n\\[\nL(f)=1-2+1=0.\n\\]\nIndeed \\(I-A\\) is singular, so Lefschetz gives no forced fixed point.', 'For \\(A=\\begin{pmatrix}a&b\\\\c&d\\end{pmatrix}\\),\n\\[\n\\det(I-A)=(1-a)(1-d)-bc\n=1-(a+d)+(ad-bc)\n=1-\\operatorname{tr}A+\\det A.\n\\]\nThis is exactly the torus Lefschetz number.', 'The trace formula gives \\(L(f)=\\det(I-A)\\). Therefore\n\\[\n\\det(I-A)\\ne0\n\\]\nis sufficient for the induced torus map to have a fixed point.', 'An orientation-reversing map \\(S^2\\to S^2\\) of degree \\(-1\\) has\n\\[\nL(f)=1+(-1)=0.\n\\]\nThus Lefschetz alone does not force a fixed point.', 'The antipodal map on \\(S^n\\) has degree \\((-1)^{n+1}\\). Hence\n\\[\nL(a)=1+(-1)^n(-1)^{n+1}=1-1=0.\n\\]', 'The antipodal map has no fixed points because \\(x=-x\\) on a sphere would imply \\(x=0\\), which is impossible. Its Lefschetz number is correspondingly zero, consistent with the theorem.', 'For the identity,\n\\[\nL(\\mathrm{id}_X)=\\sum_k(-1)^k\\operatorname{tr}(\\mathrm{id}|H_k)\n=\\sum_k(-1)^k b_k\n=\\chi(X).\n\\]', 'If \\(H_*(X;\\mathbb Q)=H_{\\mathrm{even}}\\oplus H_{\\mathrm{odd}}\\) as a graded vector space, then\n\\[\nL(f)=\\operatorname{tr}(f_*|H_{\\mathrm{even}})\n-\\operatorname{tr}(f_*|H_{\\mathrm{odd}}),\n\\]\nwhich is the supertrace.', 'The trace is defined for finite-dimensional vector spaces. A finite CW complex has finite-dimensional \\(H_k(X;\\mathbb Q)\\), and only finitely many degrees are nonzero, so the alternating trace sum is finite and well-defined.', 'Poincaré duality identifies the homology class of the diagonal with a sum built from dual homology/cohomology bases. Pairing the graph class with this diagonal class converts the graph--diagonal intersection number into the alternating traces of \\(f_*\\).', 'The same integer has three forms:\n\\[\nL(f)=\\sum_k(-1)^k\\operatorname{tr}(f_*|H_k)\n=\\Gamma_f\\cdot\\Delta\n=\\sum_{x\\in\\operatorname{Fix}(f)}\\operatorname{ind}_x(f)\n\\]\nwhen the local-index hypotheses hold. This is the algebraic, geometric, and local fixed-point synthesis of Lefschetz theory.']}

PATHS = {
31: "books/vol08_algebraic_topology/chapters/ch31_thom_classes/chapter.tex",
32: "books/vol08_algebraic_topology/chapters/ch32_sphere_bundles_and_euler_classes/chapter.tex",
33: "books/vol08_algebraic_topology/chapters/ch33_poincar_duality/chapter.tex",
34: "books/vol08_algebraic_topology/chapters/ch34_intersection_forms/chapter.tex",
35: "books/vol08_algebraic_topology/chapters/ch35_lefschetz_theory/chapter.tex",
}

def read(p):
    return p.read_text(encoding="utf-8-sig",errors="strict")

def main():
    ap=argparse.ArgumentParser()
    ap.add_argument("--repo",required=True)
    args=ap.parse_args()
    repo=Path(args.repo).resolve()

    total=0
    for ch,path in PATHS.items():
        p=repo/path
        t=read(p)
        marker=r"\section{Exercises}"
        hmarker=r"\section{Hints}"
        if marker not in t or hmarker not in t:
            # Idempotent success if already converted.
            if r"\section{Exercises, Hints, and Solutions}" in t:
                triads=len(re.findall(r"\\begin\{exercise\}",t))
                sols=len(re.findall(r"\\begin\{solution\}",t))
                probs=len(re.findall(r"\\begin\{problem\}",t))
                if triads==24 and sols>=probs+24:
                    print(f"VIII/{ch}: already completed")
                    continue
            raise SystemExit(f"VIII/{ch}: expected Exercises/Hints sections not found")

        head,tail=t.split(marker,1)
        exercises_text,hints_text=tail.split(hmarker,1)
        exs=re.findall(r"\\begin\{exercise\}(.*?)\\end\{exercise\}",exercises_text,re.S)
        hints=re.findall(r"\\begin\{hint\}(.*?)\\end\{hint\}",hints_text,re.S)
        if len(exs)!=24 or len(hints)!=24 or len(SOLUTIONS[ch])!=24:
            raise SystemExit(f"VIII/{ch}: expected 24 exercises/hints/solutions, got {len(exs)}/{len(hints)}/{len(SOLUTIONS[ch])}")

        block=[r"\section{Exercises, Hints, and Solutions}"]
        for i,(ex,hint,sol) in enumerate(zip(exs,hints,SOLUTIONS[ch]),1):
            block += [
                rf"\begin{{exercise}}\label{{exr:viii{ch:02d}-{i:02d}}}",
                ex.strip(),
                r"\end{exercise}",
                r"\begin{hint}",
                hint.strip(),
                r"\end{hint}",
                r"\begin{solution}",
                sol.strip(),
                r"\end{solution}",
                ""
            ]
        new=head + "\n".join(block).rstrip() + "\n"
        p.write_text(new,encoding="utf-8")
        total += 24
        print(f"VIII/{ch}: completed 24 exercise/hint/solution triads")

    print(f"Completed exercise solutions: {total}")

if __name__=="__main__":
    main()
